	if !in.IsKnown() {
		return NewOverallReportValueUnknown(), nil
	}

	if in.IsNull() {
		return NewOverallReportValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewOverallReportValueMust(OverallReportValue{}.AttributeTypes(ctx), attributes), nil
